-- Vitality 8-Week Challenge intake (public /challenge/intake, opened straight
-- after paying on Stripe). Temporary: one cohort, removable afterwards.
--
-- Same security model as assessments / meal_plan_requests: rows are inserted
-- server-side by /api/challenge/intake with the service-role key after the
-- answers are re-validated, so the anon key gets no policy at all (no
-- insert, select, update or delete). Only the coach can read.
create table public.challenge_intakes (
  id uuid primary key default gen_random_uuid(),
  -- Generated by the browser once per form fill; makes a double-submit land once.
  submission_id uuid not null unique,
  cohort text not null default 'oct-2026',
  full_name text not null,
  email text not null,
  phone text not null,
  instagram text,
  age int not null,
  height_cm numeric(5, 1) not null,
  weight_kg numeric(5, 1) not null,
  main_goal text not null,
  -- true when any health question was answered Yes (red badge in the coach app)
  health_flag boolean not null default false,
  -- all four agreement boxes ticked at this moment
  agreed_at timestamptz not null default now(),
  -- every answer, keyed by question id (src/lib/challenge/questions.ts)
  answers jsonb not null,
  crm_contact_id uuid references public.crm_contacts(id) on delete set null,
  created_at timestamptz not null default now()
);

create index challenge_intakes_created_at_idx on public.challenge_intakes (cohort, created_at desc);

alter table public.challenge_intakes enable row level security;

create policy "challenge_intakes_select_coach" on public.challenge_intakes for select
  using (public.is_coach());
